<template>
  <div class="space-y-6"><div class="flex items-center justify-between"><h3 class="text-2xl font-bold">Report details</h3><NuxtLink to="/reports" class="rounded-xl border border-slate-200 px-4 py-3 text-sm font-semibold">Back</NuxtLink></div><div v-if="loading" class="rounded-3xl border border-slate-200 bg-white p-6 shadow-sm">Loading...</div><div v-else-if="report" class="rounded-3xl border border-slate-200 bg-white p-6 shadow-sm"><p class="text-xl font-bold">{{ report.title }}</p><p class="mt-2 text-slate-500">Status: {{ report.status }}</p><p class="mt-4">{{ report.aiSummary }}</p></div></div>
</template>
<script setup lang="ts">const route=useRoute(); const api=useMedivoyApi(); const report=ref<any>(null); const loading=ref(true); onMounted(async()=>{ try { report.value = await api.getReport(route.params.id as string) } catch { report.value = null } finally { loading.value=false } })</script>
